const CONTINENTS = ["אפריקה", "אסיה", "אירופה", "צפון אמריקה", "דרום אמריקה", "אוקיאניה"];
const DIFFICULTIES = ["קל", "בינוני", "קשה"];

const COUNTRIES_BY_ID = {};
COUNTRIES.forEach((c) => { COUNTRIES_BY_ID[c.id] = c; });

// HTML לדגל: משתמש בספריית flag-icons לפי קוד ISO. לסומלילנד (שאינה מדינה מוכרת ב-ISO) יש נפילה חמה לאימוג'י.
function flagHtml(id) {
  if (!id || id.charAt(0) === "_") {
    return '<span class="flag-fallback" aria-hidden="true">🏳️</span>';
  }
  return '<span class="fi fi-' + id + '" aria-hidden="true"></span>';
}

// עיצוב מספר תושבים בעברית מתוך מיליוני תושבים (קירוב).
function formatPopulation(millions) {
  if (millions >= 1000) {
    return (millions / 1000).toLocaleString("he-IL", { maximumFractionDigits: 2 }) + " מיליארד תושבים (בערך)";
  }
  if (millions < 1) {
    const thousands = Math.round(millions * 1000);
    return thousands.toLocaleString("he-IL") + " תושבים (בערך)";
  }
  return millions.toLocaleString("he-IL", { maximumFractionDigits: 1 }) + " מיליון תושבים (בערך)";
}

function randomChoice(arr) {
  return arr[Math.floor(Math.random() * arr.length)];
}

function shuffle(arr) {
  const a = arr.slice();
  for (let i = a.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [a[i], a[j]] = [a[j], a[i]];
  }
  return a;
}

// רמות קושי הן קומולטיביות: קל = רק "קל", בינוני = "קל"+"בינוני", קשה = הכול (ברירת המחדל ההיסטורית).
function difficultyAtLeast(countryDifficulty, maxDifficulty) {
  const order = { קל: 0, בינוני: 1, קשה: 2 };
  if (!maxDifficulty || maxDifficulty === "קשה") return true;
  return order[countryDifficulty] <= order[maxDifficulty];
}

function countriesForContinent(continent) {
  if (!continent || continent === "world") return COUNTRIES.slice();
  return COUNTRIES.filter((c) => c.continent === continent);
}

function filterCountries(continent, difficulty) {
  return countriesForContinent(continent).filter((c) => difficultyAtLeast(c.difficulty, difficulty));
}
